package de.inrouder.fitrocket;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import android.text.*;
import org.json.*;
import java.time.*;
import java.time.format.*;
import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class MainActivity extends Activity {
  private static final int EXPORT_REQUEST=81,IMPORT_REQUEST=82;
  private final ArrayList<JSONObject> foods=new ArrayList<>(), meals=new ArrayList<>(), weights=new ArrayList<>();
  private android.content.SharedPreferences prefs;
  private LinearLayout page, entries;
  private GlassView glass;
  private TextView summary;
  private int budget=23, weekly=0;
  private final int NAVY=Color.rgb(20,48,88), BLUE=Color.rgb(41,111,218), LIGHT=Color.rgb(242,247,253);
  private String today(){return LocalDate.now().toString();}
  private String pretty(String date){try{return LocalDate.parse(date).format(DateTimeFormatter.ofPattern("dd.MM.yyyy"));}catch(Exception e){return date;}}
  private TextView label(String text,int sp){TextView t=new TextView(this);t.setText(text);t.setTextSize(sp);t.setTextColor(NAVY);t.setPadding(12,10,12,10);return t;}
  private Button button(String text){Button b=new Button(this);b.setText(text);b.setAllCaps(false);return b;}
  private EditText edit(String hint,String value,int input){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);e.setInputType(input);if(value!=null)e.setText(value);return e;}
  private void msg(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
  @Override public void onCreate(Bundle saved){super.onCreate(saved);prefs=getSharedPreferences("fitrocket",MODE_PRIVATE);budget=prefs.getInt("budget",23);weekly=prefs.getInt("weekly",0);loadFoods();readArray("meals",meals);readArray("weights",weights);home();}
  private void readArray(String key,ArrayList<JSONObject> into){into.clear();try{JSONArray arr=new JSONArray(prefs.getString(key,"[]"));for(int i=0;i<arr.length();i++)into.add(arr.getJSONObject(i));}catch(Exception ignored){}}
  private void persist(String key,ArrayList<JSONObject> items){JSONArray a=new JSONArray();for(JSONObject x:items)a.put(x);prefs.edit().putString(key,a.toString()).apply();}
  private void loadFoods(){try(InputStream in=getAssets().open("foods.json")){ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)o.write(b,0,n);JSONArray a=new JSONArray(new String(o.toByteArray(),StandardCharsets.UTF_8));for(int i=0;i<a.length();i++)foods.add(a.getJSONObject(i));}catch(Exception e){msg("Lebensmitteldatenbank konnte nicht geladen werden.");}}
  private void shell(String heading){ScrollView sc=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(1);page.setPadding(24,20,24,48);page.setBackgroundColor(LIGHT);sc.addView(page);setContentView(sc);TextView title=label("🚀 "+heading,26);title.setTypeface(null,1);page.addView(title);LinearLayout nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);for(String n:new String[]{"Heute","Suchen","Verlauf","Mehr"}){Button b=button(n);nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));b.setOnClickListener(v->{switch(n){case "Heute":home();break;case "Suchen":searchScreen();break;case "Verlauf":history();break;default:more();}});}page.addView(nav);}
  private int used(String date){int total=0;for(JSONObject x:meals)if(date.equals(x.optString("date")))total+=x.optInt("points");return total;}
  private int count(String date){int n=0;for(JSONObject x:meals)if(date.equals(x.optString("date")))n++;return n;}
  private String kind(JSONObject f){String s=f.optString("status");if(s.equals("zero"))return "0 Punkte · deutsche Historienliste";if(s.equals("historical_us"))return "0 Punkte · historische US-Liste";if(s.equals("example"))return "Richtwert (unbestätigt)";return "Prüffall · Punkte selbst eintragen";}
  private void home(){shell("FitRocket 0.3.0");page.addView(label("Heute · "+pretty(today()),16));glass=new GlassView();page.addView(glass,new LinearLayout.LayoutParams(-1,340));summary=label("",20);summary.setTypeface(null,1);page.addView(summary);int n=used(today());summary.setText(n+" / "+budget+" Punkte · "+(n<=budget?(budget-n)+" verbleiben":(n-budget)+" über Budget"));page.addView(label("Wochen-Extra: "+weekly+" (manuell festgelegt) · "+count(today())+" Einträge heute",14));Button add=button("＋ Essen suchen und eintragen");page.addView(add);add.setOnClickListener(v->searchScreen());Button quick=button("✍ Mahlzeit frei eintragen");page.addView(quick);quick.setOnClickListener(v->manual());Button assistant=button("📝 Text-Erfassung (offline)");page.addView(assistant);assistant.setOnClickListener(v->textHelper());page.addView(label("Heutiges Tagebuch",19));entries=new LinearLayout(this);entries.setOrientation(1);page.addView(entries);int shown=0;for(int i=meals.size()-1;i>=0;i--){JSONObject m=meals.get(i);if(today().equals(m.optString("date"))){shown++;mealRow(m,entries);}}if(shown==0)entries.addView(label("Noch keine Mahlzeit eingetragen.",15));page.addView(label("Hinweis: Eigene Punkteangaben und historische Richtwerte bitte überprüfen. Das Glas ist eine Motivation, keine medizinische Bewertung.",12));}
  private void mealRow(JSONObject m,LinearLayout target){LinearLayout row=new LinearLayout(this);row.setOrientation(1);TextView t=label(m.optString("name")+"  ·  "+m.optInt("points")+" P",16);row.addView(t);row.addView(label(pretty(m.optString("date"))+"  ·  "+m.optString("group","Mahlzeit")+"  ·  "+m.optString("quality","Benutzereingabe"),12));row.setBackgroundColor(Color.WHITE);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,4,0,8);target.addView(row,lp);row.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(m.optString("name")).setItems(new String[]{"Punkte bearbeiten","Eintrag löschen"},(d,choice)->{if(choice==0)editMeal(m);else new AlertDialog.Builder(this).setMessage("Eintrag wirklich löschen?").setPositiveButton("Löschen",(a,b)->{meals.remove(m);persist("meals",meals);home();}).setNegativeButton("Abbrechen",null).show();}).show());}
  private void editMeal(JSONObject m){EditText e=edit("Punkte",String.valueOf(m.optInt("points")),2);new AlertDialog.Builder(this).setTitle("Punkte anpassen").setView(e).setPositiveButton("Speichern",(d,w)->{try{int n=Integer.parseInt(e.getText().toString());if(n<0||n>2000)throw new Exception();m.put("points",n);m.put("quality","Manuell korrigiert");persist("meals",meals);home();}catch(Exception ignored){msg("Ungültige Punkte.");}}).setNegativeButton("Abbrechen",null).show();}
  private void searchScreen(){shell("Lebensmittel");page.addView(label(foods.size()+" Einträge · Suche nach Name, Alias oder Kategorie",14));EditText q=edit("Mindestens zwei Buchstaben …","",1);page.addView(q);LinearLayout list=new LinearLayout(this);list.setOrientation(1);page.addView(list);Runnable run=()->{list.removeAllViews();String query=q.getText().toString().toLowerCase(Locale.ROOT).trim();if(query.length()<2){list.addView(label("Tippe einen Suchbegriff ein.",14));return;}int hits=0;for(JSONObject f:foods){String value=(f.optString("name")+" "+f.optString("alias")+" "+f.optString("category")).toLowerCase(Locale.ROOT);if(!value.contains(query))continue;Button b=button(f.optString("name")+"  ·  "+kind(f));list.addView(b);b.setOnClickListener(v->foodDialog(f));if(++hits>=60)break;}if(hits==0)list.addView(label("Kein Treffer. Nutze die freie Eingabe und vergib Punkte manuell.",14));};q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){run.run();}public void afterTextChanged(Editable e){}});run.run();}
  private void foodDialog(JSONObject f){LinearLayout content=new LinearLayout(this);content.setPadding(22,8,22,8);content.setOrientation(1);content.addView(label(f.optString("category")+"\n"+kind(f)+"\nPortion: "+f.optString("portion")+"\n"+f.optString("notes"),14));EditText mult=edit("Portionsfaktor","1",8194),points=edit("Punkte pro Portion",f.isNull("points")?"":String.valueOf(f.optInt("points")),2);content.addView(label("Portionsfaktor: bei 150 g Referenzportion z. B. 0,5 für 75 g",13));content.addView(mult);content.addView(points);Spinner group=groupSpinner();content.addView(group);AlertDialog d=new AlertDialog.Builder(this).setTitle(f.optString("name")).setView(content).setNegativeButton("Abbrechen",null).setPositiveButton("Buchen",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(btn->{try{double factor=Double.parseDouble(mult.getText().toString().replace(',','.'));int pointsPer=Integer.parseInt(points.getText().toString());if(!Double.isFinite(factor)||factor<=0||factor>100||pointsPer<0||pointsPer>2000)throw new Exception();int total=(int)Math.round(pointsPer*factor);if(total>2000)throw new Exception();addMeal(f.optString("name")+" × "+factor,total,f.optString("id"),kind(f),group.getSelectedItem().toString());d.dismiss();home();}catch(Exception ex){msg("Bitte gültige Portion und Punkte eingeben.");}}));d.show();}
  private Spinner groupSpinner(){Spinner s=new Spinner(this);String[] groups={"Frühstück","Mittagessen","Abendessen","Snack","Getränke"};ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,groups);s.setAdapter(a);return s;}
  private void addMeal(String name,int points,String foodId,String quality,String group){try{JSONObject x=new JSONObject();x.put("name",name);x.put("points",points);x.put("foodId",foodId);x.put("quality",quality);x.put("group",group);x.put("date",today());meals.add(x);persist("meals",meals);}catch(Exception e){msg("Speichern fehlgeschlagen.");}}
  private void manual(){LinearLayout l=new LinearLayout(this);l.setPadding(22,4,22,4);l.setOrientation(1);EditText name=edit("Lebensmittel / Gericht","",1),points=edit("Punkte (manuell)",null,2);l.addView(name);l.addView(points);Spinner g=groupSpinner();l.addView(g);AlertDialog d=new AlertDialog.Builder(this).setTitle("Manuell erfassen").setView(l).setNegativeButton("Abbrechen",null).setPositiveButton("Eintragen",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(btn->{try{String n=name.getText().toString().trim();int p=Integer.parseInt(points.getText().toString());if(n.length()<2||p<0||p>2000)throw new Exception();addMeal(n,p,"","Manuell",g.getSelectedItem().toString());d.dismiss();home();}catch(Exception ex){msg("Bitte Name und gültige Punkte angeben.");}}));d.show();}
  private void textHelper(){EditText input=new EditText(this);input.setMinLines(3);input.setHint("Beispiel: Ich hatte eine Banane und einen Apfel");new AlertDialog.Builder(this).setTitle("Offline-Texterfassung (keine KI)").setMessage("Erkennt eindeutige Lebensmittelnamen aus deiner Datenbank. Mengen und Zutaten müssen vor dem Eintragen geprüft werden.").setView(input).setPositiveButton("Analysieren",(d,w)->interpret(input.getText().toString())).setNegativeButton("Abbrechen",null).show();}
  private void interpret(String source){String q=source.toLowerCase(Locale.ROOT);ArrayList<JSONObject> matches=new ArrayList<>();for(JSONObject f:foods){String name=f.optString("name").toLowerCase(Locale.ROOT);if(name.length()>=5&&q.contains(name))matches.add(f);}if(matches.size()!=1){new AlertDialog.Builder(this).setTitle("Bitte Lebensmittel auswählen").setMessage(matches.isEmpty()?"Keine eindeutige Übereinstimmung gefunden. Bitte suche das Lebensmittel manuell.":"Mehrere Lebensmittel erkannt. Bitte erfasse die Zutaten einzeln über die Suche.").setPositiveButton("Zur Suche",(d,w)->searchScreen()).show();return;}foodDialog(matches.get(0));}
  private void history(){shell("Tagebuch");page.addView(label("Alle gespeicherten Mahlzeiten · Tippen zum Bearbeiten/Löschen",15));for(int i=meals.size()-1;i>=0;i--)mealRow(meals.get(i),page);if(meals.isEmpty())page.addView(label("Noch keine gespeicherten Einträge.",15));}
  private void more(){shell("Auswertungen & Einstellungen");Button week=button("📈 Wochen- und Monatsauswertung");page.addView(week);week.setOnClickListener(v->statistics());Button weight=button("⚖ Gewicht erfassen und Verlauf ansehen");page.addView(weight);weight.setOnClickListener(v->weightDialog());Button settings=button("⚙ Budget & Wochen-Extra");page.addView(settings);settings.setOnClickListener(v->settingsDialog());Button backup=button("⬆ Backup exportieren (JSON)");page.addView(backup);backup.setOnClickListener(v->startExport());Button restore=button("⬇ Backup importieren");page.addView(restore);restore.setOnClickListener(v->startImport());page.addView(label("FitRocket 0.3.0 · lokal und offline\nGoogle-Login, Cloud-KI und Health Connect sind noch nicht integriert. Punktwerte sind nicht durch einen offiziellen WW-Rechner abgesichert.",14));}
  private void settingsDialog(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(25,5,25,5);EditText b=edit("Tagesbudget",String.valueOf(budget),2),w=edit("Wochen-Extra",String.valueOf(weekly),2);l.addView(label("Tagesbudget (persönlich festlegen)",14));l.addView(b);l.addView(label("Wochen-Extra (frei einstellbar; keine automatische WW-Ermittlung)",14));l.addView(w);new AlertDialog.Builder(this).setTitle("Budget").setView(l).setPositiveButton("Speichern",(d,n)->{try{int bb=Integer.parseInt(b.getText().toString()),ww=Integer.parseInt(w.getText().toString());if(bb<1||bb>200||ww<0||ww>500)throw new Exception();budget=bb;weekly=ww;prefs.edit().putInt("budget",bb).putInt("weekly",ww).apply();more();}catch(Exception e){msg("Ungültige Budgetwerte.");}}).setNegativeButton("Abbrechen",null).show();}
  private void statistics(){shell("Statistiken");LocalDate now=LocalDate.now(),start=now.minusDays(now.getDayOfWeek().getValue()-1);page.addView(label("Diese Woche",20));int weeklyUsed=0;for(int i=0;i<7;i++){LocalDate date=start.plusDays(i);int n=used(date.toString());weeklyUsed+=n;page.addView(label(date.getDayOfWeek().toString().substring(0,2)+" "+pretty(date.toString())+": "+n+" Punkte",15));}page.addView(label("Gesamt: "+weeklyUsed+" Punkte; Ø "+String.format(Locale.GERMAN,"%.1f",weeklyUsed/7.0)+" pro Kalendertag",15));page.addView(label("Dieser Monat",20));LocalDate first=now.withDayOfMonth(1);int total=0,tracked=0,days=now.getDayOfMonth();for(int i=0;i<days;i++){String day=first.plusDays(i).toString();total+=used(day);if(count(day)>0)tracked++;}page.addView(label("Erfasste Punkte: "+total+" · Tage mit Einträgen: "+tracked+" / "+days,16));page.addView(label("Ø je dokumentiertem Tag: "+(tracked>0?String.format(Locale.GERMAN,"%.1f",total/(double)tracked):"–"),16));page.addView(label("Achtung: Fehlende Tage gelten nicht als Null-Punkte-Tage.",13));if(!weights.isEmpty()){page.addView(label("Gewichtseinträge: "+weights.size(),16));for(int i=weights.size()-1;i>=Math.max(0,weights.size()-8);i--)page.addView(label(pretty(weights.get(i).optString("date"))+" · "+weights.get(i).optString("kg")+" kg",14));}}
  private void weightDialog(){LinearLayout l=new LinearLayout(this);l.setPadding(20,5,20,5);l.setOrientation(1);EditText e=edit("Gewicht in kg, z. B. 78,5","",8194);l.addView(e);new AlertDialog.Builder(this).setTitle("Gewicht dokumentieren").setView(l).setPositiveButton("Speichern",(d,w)->{try{double kg=Double.parseDouble(e.getText().toString().replace(',','.'));if(!Double.isFinite(kg)||kg<20||kg>400)throw new Exception();JSONObject x=new JSONObject();x.put("date",today());x.put("kg",kg);weights.add(x);persist("weights",weights);statistics();}catch(Exception ex){msg("Gewicht ungültig.");}}).setNegativeButton("Abbrechen",null).show();}
  private void startExport(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"FitRocket-Backup-"+today()+".json");startActivityForResult(i,EXPORT_REQUEST);}
  private void startImport(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");startActivityForResult(i,IMPORT_REQUEST);}
  @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==EXPORT_REQUEST){try(OutputStream os=getContentResolver().openOutputStream(uri)){JSONObject root=new JSONObject();root.put("schemaVersion",1);root.put("budget",budget);root.put("weekly",weekly);root.put("meals",new JSONArray(prefs.getString("meals","[]")));root.put("weights",new JSONArray(prefs.getString("weights","[]")));os.write(root.toString(2).getBytes(StandardCharsets.UTF_8));msg("Backup gespeichert.");}catch(Exception e){msg("Backup fehlgeschlagen.");}}else if(request==IMPORT_REQUEST){try(InputStream in=getContentResolver().openInputStream(uri)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>5_000_000)throw new IOException("Datei zu groß");}JSONObject root=new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));if(root.optInt("schemaVersion")!=1||!root.has("meals")||!root.has("weights"))throw new Exception();JSONArray ma=root.getJSONArray("meals"),we=root.getJSONArray("weights");if(ma.length()>50000||we.length()>50000)throw new Exception();int bb=root.optInt("budget",23),ww=root.optInt("weekly",0);if(bb<1||bb>200||ww<0||ww>500)throw new Exception();new AlertDialog.Builder(this).setTitle("Backup wirklich importieren?").setMessage("Vorhandene Mahlzeiten und Gewichtseinträge werden ersetzt. "+ma.length()+" Mahlzeiten im Backup.").setPositiveButton("Importieren",(d,w)->{prefs.edit().putString("meals",ma.toString()).putString("weights",we.toString()).putInt("budget",bb).putInt("weekly",ww).apply();budget=bb;weekly=ww;readArray("meals",meals);readArray("weights",weights);home();msg("Backup importiert.");}).setNegativeButton("Abbrechen",null).show();}catch(Exception e){msg("Import fehlgeschlagen: Datei ungültig.");}}}
  private class GlassView extends View {
    final Paint p=new Paint(3);GlassView(){super(MainActivity.this);}
    @Override protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight(),l=w*.22f,r=w*.78f,t=18,b=h-64;int n=used(today());float share=n/(float)Math.max(1,budget);p.setColor(Color.rgb(215,231,250));c.drawRoundRect(l,t,r,b,28,28,p);p.setColor(share>1?Color.rgb(245,117,69):Color.rgb(56,154,235));float fill=Math.min(1,share);if(fill>0)c.drawRect(l+9,b-9-(b-t-18)*fill,r-9,b-9,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(7);p.setColor(BLUE);c.drawRoundRect(l,t,r,b,28,28,p);p.setStyle(Paint.Style.FILL);p.setTextAlign(Paint.Align.CENTER);p.setColor(NAVY);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(43);c.drawText(n+" / "+budget,w/2,(b+t)/2,p);p.setTextSize(19);c.drawText(n>budget?"Troll wischt den Überlauf!":"Das magische Punkteglas",w/2,h-15,p);if(share>1){p.setColor(Color.rgb(240,118,68));c.drawOval(r+8,t+25,r+38,t+105,p);p.setColor(NAVY);c.drawCircle(r+19,t+25,5,p);}}
  }
}
